mod fallback_contract {
    use super::*;
    use crate::domain::models::entity_search::SearchMatchSource;
    use crate::outbound::ExposedDatabase;
    use sqlx::PgPool;

    fn request(term: &str, limit: u8) -> EntitySearchRequest {
        EntitySearchRequest::new_with_strictness(term.into(), limit, 0.8).unwrap()
    }

    #[sqlx::test(
        migrations = "../db/migrations",
        fixtures("../../../../../db/fixtures/add_members.sql")
    )]
    async fn primary_people_suppress_fallback_before_limits(pool: PgPool) -> sqlx::Result<()> {
        let db = ExposedDatabase::from(pool.clone());
        let service = Service::new(db.clone(), db);
        let company = uuid::Uuid::from_u128(1);
        let person = uuid::Uuid::from_u128(2);
        sqlx::query!("INSERT INTO exposed.funders (id, funder_name, funder_kind) VALUES ($1, 'Jahn', 'Company'), ($2, 'Jahn Person', 'Individual')", company, person).execute(&pool).await?;
        let results = service.search_entities(&request("jahn", 1)).await.unwrap();
        assert_eq!(
            results.iter().map(Entity::name).collect::<Vec<_>>(),
            vec!["Jahn"]
        );
        let results = service.search_entities(&request("jahn", 10)).await.unwrap();
        assert_eq!(
            results.iter().map(Entity::name).collect::<Vec<_>>(),
            vec!["Jahn", "Jahn Person"]
        );
        sqlx::query!("INSERT INTO exposed.funders (funder_name, funder_kind) VALUES ('Jahn Fallback', 'Individual')").execute(&pool).await?;
        let results = service.search_entities(&request("john", 10)).await.unwrap();
        assert_eq!(results.len(), 2);
        assert!(
            results
                .iter()
                .all(|entity| matches!(entity, Entity::ParliamentMember(_)))
        );
        Ok(())
    }

    #[sqlx::test(migrations = "../db/migrations")]
    async fn aliases_deduplicate_and_share_the_funder_cap(pool: PgPool) -> sqlx::Result<()> {
        let person = uuid::Uuid::from_u128(1);
        sqlx::query!("INSERT INTO exposed.funders (id, funder_name, funder_kind) VALUES ($1, 'Unrelated Identity', 'Individual')", person).execute(&pool).await?;
        for alias in ["John", "JOHN", "John Smith"] {
            sqlx::query!(
                "INSERT INTO exposed.funder_aliases (funder_id, funder_alias) VALUES ($1, $2)",
                person,
                alias
            )
            .execute(&pool)
            .await?;
        }
        sqlx::query!("INSERT INTO exposed.funders (funder_name, funder_kind) VALUES ('Jahn Foundation', 'Company'), ('John Brown', 'Individual'), ('John Company', 'Company')").execute(&pool).await?;
        let db = ExposedDatabase::from(pool);
        let service = Service::new(db.clone(), db);
        let results = service.search_entities(&request("jahn", 2)).await.unwrap();
        assert_eq!(
            results.iter().map(Entity::name).collect::<Vec<_>>(),
            vec!["Jahn Foundation", "Unrelated Identity"]
        );
        let Entity::Funder(found) = &results[1] else {
            panic!("expected funder");
        };
        assert_eq!(found.funder().id().value(), person);
        assert_eq!(
            found.source(),
            &SearchMatchSource::Alias {
                name: "JOHN".into()
            }
        );
        Ok(())
    }

    #[sqlx::test(migrations = "../db/migrations")]
    async fn words_require_distinct_positions_and_bounded_distance(
        pool: PgPool,
    ) -> sqlx::Result<()> {
        for (query, candidate, expected) in [
            ("jahn mcdonnell", "John McDonnell", Some(1)),
            ("jahn unrelated", "John McDonnell", None),
            ("jahn jahn", "John", None),
            ("jahn jahn", "John John", Some(2)),
            ("jahn", "Sir John Smith", Some(1)),
            ("jahn", "Jonathan", None),
            ("!!!", "John", None),
        ] {
            let actual = sqlx::query_scalar!(
                "SELECT exposed.person_name_distance($1, $2)",
                query,
                candidate
            )
            .fetch_one(&pool)
            .await?;
            assert_eq!(actual, expected, "{query} / {candidate}");
        }
        let long = "a".repeat(256);
        for (query, candidate) in [
            (format!("john {long}"), "John".to_owned()),
            ("john".to_owned(), long),
        ] {
            let actual = sqlx::query_scalar!(
                "SELECT exposed.person_name_distance($1, $2)",
                query,
                candidate
            )
            .fetch_one(&pool)
            .await?;
            assert_eq!(actual, None);
        }
        Ok(())
    }

    #[sqlx::test(migrations = "../db/migrations")]
    async fn ambiguous_words_find_minimum_assignment_within_timeout(
        pool: PgPool,
    ) -> sqlx::Result<()> {
        let mut transaction = pool.begin().await?;
        sqlx::query!("SET LOCAL statement_timeout = '2s'")
            .execute(&mut *transaction)
            .await?;
        let candidate = (0..10)
            .map(|index| format!("john{index}"))
            .collect::<Vec<_>>()
            .join(" ");
        let nonexact = (0..10)
            .map(|index| format!("joan{index}"))
            .collect::<Vec<_>>()
            .join(" ");
        for (query, candidate, expected) in [
            (candidate.as_str(), candidate.as_str(), 0),
            (nonexact.as_str(), candidate.as_str(), 10),
            ("john jahn", "john joan", 2),
        ] {
            let actual = sqlx::query_scalar!(
                "SELECT exposed.person_name_distance($1, $2)",
                query,
                candidate
            )
            .fetch_one(&mut *transaction)
            .await?;
            assert_eq!(actual, Some(expected), "{query} / {candidate}");
        }
        transaction.rollback().await?;
        Ok(())
    }

    #[sqlx::test(migrations = "../db/migrations")]
    async fn ranks_by_distance_before_repository_limit(pool: PgPool) -> sqlx::Result<()> {
        sqlx::query!("INSERT INTO exposed.funders (funder_name, funder_kind) VALUES ('John Smith', 'Individual'), ('Jahn Smith Extra Words', 'Individual')").execute(&pool).await?;
        let db = ExposedDatabase::from(pool);
        let rows = db
            .get_funders_by_phonetic_search(&request("jahn smyth", 1))
            .await
            .unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].0.funder().name(), "Jahn Smith Extra Words");
        Ok(())
    }
}
The frontend image is for local development. `npm run build` produces static
assets in `frontend/dist`; a production host must also route `/api/search` to
the Rust API.

The similarity threshold slider refreshes results automatically: lower values
include broader matches, from 0 to 1 in steps of 0.01 (default 0.8). The search URL
preserves the query and threshold, for example `/?q=John&strictness=0.65`.
Search delay, result limits and defaults live in
[`frontend/src/lib/search.ts`](frontend/src/lib/search.ts). The API caps each entity type separately, so the UI describes the returned
results without claiming a total count or offering unsupported pagination.
The API also defaults to `0.8` when `strictness` is omitted. Explicit thresholds
control primary trigram matches. When these contain no MP or Individual funder,
search appends phonetic person matches after the primary results. Organization
matches do not suppress this fallback. Each query word must match a distinct
name word with the same Soundex code and at most one edit. Extra name words are
allowed; words from different aliases cannot combine. Fallback results rank by
total edits, then trigram similarity and stable identity. Canonical names win
alias ties. Primary and fallback funders share the per-type result limit.

In-app feedback collection is future work. Feedback is gathered through manual
testing.

For frontend checks, install dependencies and the browser once, then run:

```sh
npm --prefix frontend ci
cd frontend && PLAYWRIGHT_BROWSERS_PATH=0 npx playwright install chromium && cd ..
make frontend-check
```

Browser tests use a controlled API to check ranking, request cancellation,
empty/error recovery, text escaping and narrow layouts. For manual verification,
try an MP's name, `HSBC`, a misspelling, clearing a pending query, and stopping
the API to check retry behavior. See the
[search design brief](docs/design/entity-search.md) for the agreed scope.

CREATE EXTENSION fuzzystrmatch WITH SCHEMA exposed;

CREATE FUNCTION exposed.person_name_words(value text) RETURNS text[]
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
    SELECT COALESCE(array_agg(word), ARRAY[]::text[])
    FROM regexp_split_to_table(lower(value), '[^[:alnum:]]+') AS word
    WHERE word <> ''
$$;

CREATE FUNCTION exposed.person_name_codes(value text) RETURNS text[]
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
    SELECT COALESCE(array_agg(exposed.soundex(word)), ARRAY[]::text[])
    FROM unnest(exposed.person_name_words(value)) AS word
$$;

CREATE FUNCTION exposed.person_name_distance(query text, candidate text) RETURNS integer
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE AS $$
DECLARE
    query_words text[] := exposed.person_name_words(query);
    candidate_words text[] := exposed.person_name_words(candidate);
    query_count integer := cardinality(query_words);
    candidate_count integer := cardinality(candidate_words);
    invalid_cost integer := query_count + 1;
    costs integer[][];
    query_potential integer[];
    candidate_potential integer[];
    assigned_query integer[];
    predecessor integer[];
    minimum_cost integer[];
    visited boolean[];
    query_position integer;
    candidate_position integer;
    current_candidate integer;
    next_candidate integer;
    current_query integer;
    reduced_cost integer;
    potential_change integer;
    distance integer;
    total_distance integer := 0;
BEGIN
    IF query_count = 0 OR query_count > candidate_count
       OR EXISTS (SELECT FROM unnest(query_words) word WHERE char_length(word) > 255) THEN
        RETURN NULL;
    END IF;

    -- Any invalid edge costs more than an entire valid assignment.
    costs := array_fill(invalid_cost, ARRAY[query_count, candidate_count]);
    FOR query_position IN 1..query_count LOOP
        FOR candidate_position IN 1..candidate_count LOOP
            IF char_length(candidate_words[candidate_position]) <= 255
               AND exposed.soundex(query_words[query_position]) = exposed.soundex(candidate_words[candidate_position]) THEN
                distance := exposed.levenshtein_less_equal(query_words[query_position], candidate_words[candidate_position], 1);
                IF distance <= 1 THEN
                    costs[query_position][candidate_position] := distance;
                END IF;
            END IF;
        END LOOP;
    END LOOP;

    query_potential := array_fill(0, ARRAY[query_count + 1], ARRAY[0]);
    candidate_potential := array_fill(0, ARRAY[candidate_count + 1], ARRAY[0]);
    assigned_query := array_fill(0, ARRAY[candidate_count + 1], ARRAY[0]);
    predecessor := array_fill(0, ARRAY[candidate_count + 1], ARRAY[0]);

    -- Hungarian assignment uses position zero as the augmenting path's root.
    FOR query_position IN 1..query_count LOOP
        assigned_query[0] := query_position;
        current_candidate := 0;
        minimum_cost := array_fill(NULL::integer, ARRAY[candidate_count + 1], ARRAY[0]);
        visited := array_fill(false, ARRAY[candidate_count + 1], ARRAY[0]);
        LOOP
            visited[current_candidate] := true;
            current_query := assigned_query[current_candidate];
            potential_change := NULL;
            FOR candidate_position IN 1..candidate_count LOOP
                IF NOT visited[candidate_position] THEN
                    reduced_cost := costs[current_query][candidate_position]
                        - query_potential[current_query] - candidate_potential[candidate_position];
                    IF minimum_cost[candidate_position] IS NULL OR reduced_cost < minimum_cost[candidate_position] THEN
                        minimum_cost[candidate_position] := reduced_cost;
                        predecessor[candidate_position] := current_candidate;
                    END IF;
                    IF potential_change IS NULL OR minimum_cost[candidate_position] < potential_change THEN
                        potential_change := minimum_cost[candidate_position];
                        next_candidate := candidate_position;
                    END IF;
                END IF;
            END LOOP;
            FOR candidate_position IN 0..candidate_count LOOP
                IF visited[candidate_position] THEN
                    query_potential[assigned_query[candidate_position]] :=
                        query_potential[assigned_query[candidate_position]] + potential_change;
                    candidate_potential[candidate_position] := candidate_potential[candidate_position] - potential_change;
                ELSE
                    minimum_cost[candidate_position] := minimum_cost[candidate_position] - potential_change;
                END IF;
            END LOOP;
            current_candidate := next_candidate;
            EXIT WHEN assigned_query[current_candidate] = 0;
        END LOOP;
        LOOP
            next_candidate := predecessor[current_candidate];
            assigned_query[current_candidate] := assigned_query[next_candidate];
            current_candidate := next_candidate;
            EXIT WHEN current_candidate = 0;
        END LOOP;
    END LOOP;

    FOR candidate_position IN 1..candidate_count LOOP
        IF assigned_query[candidate_position] <> 0 THEN
            distance := costs[assigned_query[candidate_position]][candidate_position];
            IF distance = invalid_cost THEN
                RETURN NULL;
            END IF;
            total_distance := total_distance + distance;
        END IF;
    END LOOP;
    RETURN total_distance;
END
$$;

